import React, { useState } from 'react';
import './MultiTriggerAnalyzer.css';
import { PeurQueAnalyzer } from '../utils/peurQueAnalyzer';
import { AvantQueAnalyzer } from '../utils/avantQueAnalyzer';
import { UniversalAntiExpletive } from '../utils/universalAntiExpletive';
import { RegisterDetection } from '../utils/registerDetection';

const MultiTriggerAnalyzer = () => {
  const [selectedTrigger, setSelectedTrigger] = useState('peur-que');
  const [inputText, setInputText] = useState('');
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [comparisonMode, setComparisonMode] = useState(false);
  const [comparisonResults, setComparisonResults] = useState(null);

  // Corpus statistics from our previous analysis
  const triggerStats = {
    'peur-que': {
      name: 'Peur que',
      accuracy: '91.2%',
      corpusSize: 796,
      expletiveRate: '50%',
      description: 'Fear expressions with emotional intensity detection'
    },
    'avant-que': {
      name: 'Avant que',
      accuracy: '87.8%',
      corpusSize: 1200,
      expletiveRate: '35%',
      description: 'Temporal expressions with urgency analysis'
    }
  };

  const analyzeSentence = async (text, trigger) => {
    setLoading(true);
    try {
      // Universal anti-expletive check first
      const universalCheck = UniversalAntiExpletive.analyze(text);
      if (universalCheck.isAntiExpletive) {
        return {
          prediction: 'No Expletive',
          confidence: universalCheck.confidence,
          reasoning: universalCheck.reasoning,
          likelihood: universalCheck.likelihood,
          trigger: trigger,
          universalOverride: true
        };
      }

      // Register detection
      const registerInfo = RegisterDetection.analyze(text);

      // Trigger-specific analysis
      let analysis;
      if (trigger === 'peur-que') {
        analysis = PeurQueAnalyzer.analyze(text);
      } else if (trigger === 'avant-que') {
        analysis = AvantQueAnalyzer.analyze(text);
      }

      // Apply register effects
      const adjustedConfidence = analysis.confidence + registerInfo.adjustment;

      return {
        prediction: analysis.prediction,
        confidence: Math.min(100, Math.max(0, adjustedConfidence)),
        reasoning: analysis.reasoning,
        likelihood: analysis.likelihood,
        trigger: trigger,
        registerInfo: registerInfo,
        semanticDomains: analysis.semanticDomains,
        emotionalIntensity: analysis.emotionalIntensity
      };
    } catch (error) {
      console.error('Analysis error:', error);
      return {
        prediction: 'Error',
        confidence: 0,
        reasoning: 'Analysis failed: ' + error.message,
        trigger: trigger
      };
    } finally {
      setLoading(false);
    }
  };

  const handleAnalyze = async () => {
    if (!inputText.trim()) return;

    if (comparisonMode) {
      // Analyze with both triggers
      const peurQueResult = await analyzeSentence(inputText, 'peur-que');
      const avantQueResult = await analyzeSentence(inputText, 'avant-que');

      setComparisonResults({
        'peur-que': peurQueResult,
        'avant-que': avantQueResult
      });
      setResults(null);
    } else {
      // Single trigger analysis
      const result = await analyzeSentence(inputText, selectedTrigger);
      setResults(result);
      setComparisonResults(null);
    }
  };

  const renderSingleResult = (result) => {
    if (!result) return null;

    return (
      <div className="analysis-result">
        <div className="result-header">
          <h3>Analysis Result</h3>
          <div className="trigger-badge">{triggerStats[result.trigger].name}</div>
        </div>

        <div className="result-summary">
          <div className="prediction">
            <strong>Prediction:</strong> {result.prediction}
          </div>
          <div className="confidence">
            <strong>Confidence:</strong> {result.confidence.toFixed(1)}%
          </div>
          <div className="likelihood">
            <strong>Expletive Likelihood:</strong> {result.likelihood}/7
          </div>
        </div>

        <div className="result-details">
          <h4>Analysis Details</h4>
          <div className="reasoning">
            <strong>Reasoning:</strong> {result.reasoning}
          </div>

          {result.registerInfo && (
            <div className="register-info">
              <strong>Register:</strong> {result.registerInfo.register} 
              (adjustment: {result.registerInfo.adjustment > 0 ? '+' : ''}{result.registerInfo.adjustment}%)
            </div>
          )}

          {result.semanticDomains && (
            <div className="semantic-domains">
              <strong>Semantic Domains:</strong> {result.semanticDomains.join(', ')}
            </div>
          )}

          {result.emotionalIntensity && (
            <div className="emotional-intensity">
              <strong>Emotional Intensity:</strong> {result.emotionalIntensity}
            </div>
          )}

          {result.universalOverride && (
            <div className="universal-override">
              <strong>Universal Rule Applied:</strong> Anti-expletive context detected
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderComparisonResults = () => {
    if (!comparisonResults) return null;

    return (
      <div className="comparison-results">
        <h3>Cross-Trigger Comparison</h3>
        <div className="comparison-grid">
          {Object.entries(comparisonResults).map(([trigger, result]) => (
            <div key={trigger} className="comparison-item">
              <div className="comparison-header">
                <h4>{triggerStats[trigger].name}</h4>
                <div className="trigger-stats">
                  Accuracy: {triggerStats[trigger].accuracy} | 
                  Corpus: {triggerStats[trigger].corpusSize} sentences
                </div>
              </div>

              <div className="comparison-result">
                <div className="prediction-row">
                  <span className="label">Prediction:</span>
                  <span className={`prediction ${result.prediction.toLowerCase().replace(' ', '-')}`}>
                    {result.prediction}
                  </span>
                </div>
                <div className="confidence-row">
                  <span className="label">Confidence:</span>
                  <span className="confidence">{result.confidence.toFixed(1)}%</span>
                </div>
                <div className="likelihood-row">
                  <span className="label">Likelihood:</span>
                  <span className="likelihood">{result.likelihood}/7</span>
                </div>
              </div>

              <div className="reasoning-summary">
                {result.reasoning.substring(0, 100)}...
              </div>
            </div>
          ))}
        </div>

        <div className="comparison-insights">
          <h4>Cross-Trigger Insights</h4>
          <p>
            This comparison shows how different trigger-specific models analyze the same sentence.
            Differences in predictions highlight the specialized patterns each trigger has learned
            from its respective corpus.
          </p>
        </div>
      </div>
    );
  };

  return (
    <div className="multi-trigger-analyzer">
      <div className="analyzer-header">
        <h2>Multi-Trigger French Expletive Analysis</h2>
        <p>Advanced corpus-driven analysis with trigger-specific specialization</p>
      </div>

      <div className="trigger-selection">
        <h3>Select Analysis Mode</h3>
        <div className="mode-controls">
          <div className="trigger-options">
            <label className="trigger-option">
              <input
                type="radio"
                value="peur-que"
                checked={selectedTrigger === 'peur-que' && !comparisonMode}
                onChange={(e) => {
                  setSelectedTrigger(e.target.value);
                  setComparisonMode(false);
                }}
              />
              <div className="trigger-card">
                <h4>Peur que Analysis</h4>
                <div className="trigger-stats">
                  <div>Accuracy: {triggerStats['peur-que'].accuracy}</div>
                  <div>Corpus: {triggerStats['peur-que'].corpusSize} sentences</div>
                  <div>Expletive Rate: {triggerStats['peur-que'].expletiveRate}</div>
                </div>
                <p>{triggerStats['peur-que'].description}</p>
              </div>
            </label>

            <label className="trigger-option">
              <input
                type="radio"
                value="avant-que"
                checked={selectedTrigger === 'avant-que' && !comparisonMode}
                onChange={(e) => {
                  setSelectedTrigger(e.target.value);
                  setComparisonMode(false);
                }}
              />
              <div className="trigger-card">
                <h4>Avant que Analysis</h4>
                <div className="trigger-stats">
                  <div>Accuracy: {triggerStats['avant-que'].accuracy}</div>
                  <div>Corpus: {triggerStats['avant-que'].corpusSize} sentences</div>
                  <div>Expletive Rate: {triggerStats['avant-que'].expletiveRate}</div>
                </div>
                <p>{triggerStats['avant-que'].description}</p>
              </div>
            </label>

            <label className="trigger-option">
              <input
                type="radio"
                value="comparison"
                checked={comparisonMode}
                onChange={() => setComparisonMode(true)}
              />
              <div className="trigger-card comparison-card">
                <h4>Cross-Trigger Comparison</h4>
                <div className="trigger-stats">
                  <div>Compare Both Models</div>
                  <div>Educational Analysis</div>
                  <div>Feature Transparency</div>
                </div>
                <p>Analyze with both triggers to compare specialized patterns</p>
              </div>
            </label>
          </div>
        </div>
      </div>

      <div className="input-section">
        <h3>Enter French Sentence</h3>
        <textarea
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
          placeholder="Enter a French sentence with removed 'ne' marker..."
          className="sentence-input"
          rows={3}
        />
        <button 
          onClick={handleAnalyze}
          disabled={loading || !inputText.trim()}
          className="analyze-button"
        >
          {loading ? 'Analyzing...' : comparisonMode ? 'Compare Triggers' : 'Analyze Sentence'}
        </button>
      </div>

      <div className="results-section">
        {comparisonMode ? renderComparisonResults() : renderSingleResult(results)}
      </div>

      <div className="system-info">
        <h3>System Information</h3>
        <div className="info-grid">
          <div className="info-item">
            <h4>Universal Anti-Expletive Detection</h4>
            <p>95% accuracy across all triggers for contexts that systematically avoid expletive "ne"</p>
          </div>
          <div className="info-item">
            <h4>Register-Aware Analysis</h4>
            <p>Automatic detection of formal, informal, and literary registers with corpus-calibrated effects</p>
          </div>
          <div className="info-item">
            <h4>Corpus-Driven Features</h4>
            <p>Feature weights derived from empirical usage patterns rather than theoretical assumptions</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MultiTriggerAnalyzer;
